/* documentation is in ftcalc.h */
FT_EXPORT_DEF(void)
FT_MulTo64(FT_Int32   x,
           FT_Int32   y,
           FT_Int64  *z)
{
    FT_Int32  s;
    s  = x;
    x = FT_ABS(x);
    s ^= y;
    y = FT_ABS(y);
    ft_multo64(x, y, z);
    if (s < 0) {
        z->lo = (FT_UInt32) - (FT_Int32)z->lo;
        z->hi = ~z->hi + !(z->lo);
    }
}
