{
    FT_Int32   s;
    FT_UInt32  q;
    s  = x->hi;
    if (s < 0) {
        x->lo = (FT_UInt32) - (FT_Int32)x->lo;
        x->hi = ~x->hi + !x->lo;
    }
    s ^= y;
    y = FT_ABS(y);
    /* Shortcut */
    if (x->hi == 0) {
        if (y > 0) {
            q = (x->lo + (y >> 1)) / y;
        } else {
            q = 0x7FFFFFFFL;
        }
        return (s < 0 ? -(FT_Int32)q : (FT_Int32)q);
    }
    q = ft_div64by32(x->hi, x->lo, y);
    return (s < 0 ? -(FT_Int32)q : (FT_Int32)q);
}
