/* documentation is in ftoutln.h */
FT_EXPORT_DEF(FT_Error)
FT_Outline_EmboldenXY(FT_Outline  *outline,
                      FT_Pos       xstrength,
                      FT_Pos       ystrength)
{
    FT_Vector  *points;
    FT_Vector   v_prev, v_first, v_next, v_cur;
    FT_Int      c, n, first;
    FT_Int      orientation;
    if (!outline) {
        return FT_Err_Invalid_Argument;
    }
    xstrength /= 2;
    ystrength /= 2;
    if (xstrength == 0 && ystrength == 0) {
        return FT_Err_Ok;
    }
    orientation = FT_Outline_Get_Orientation(outline);
    if (orientation == FT_ORIENTATION_NONE) {
        if (outline->n_contours) {
            return FT_Err_Invalid_Argument;
        } else {
            return FT_Err_Ok;
        }
    }
    points = outline->points;
    first = 0;
    for (c = 0; c < outline->n_contours; c++) {
        FT_Vector  in, out, shift;
        FT_Fixed   l_in, l_out, l, q, d;
        int        last = outline->contours[c];
        v_first = points[first];
        v_prev  = points[last];
        v_cur   = v_first;
        /* compute the incoming vector and its length */
        in.x = v_cur.x - v_prev.x;
        in.y = v_cur.y - v_prev.y;
        l_in = FT_Vector_Length(&in);
        for (n = first; n <= last; n++) {
            if (n < last) {
                v_next = points[n + 1];
            } else {
                v_next = v_first;
            }
            /* compute the outgoing vector and its length */
            out.x = v_next.x - v_cur.x;
            out.y = v_next.y - v_cur.y;
            l_out = FT_Vector_Length(&out);
            d = l_in * l_out + in.x * out.x + in.y * out.y;
            /* shift only if turn is less then ~160 degrees */
            if (16 * d > l_in * l_out) {
                /* shift components are aligned along bisector        */
                /* and directed according to the outline orientation. */
                shift.x = l_out * in.y + l_in * out.y;
                shift.y = l_out * in.x + l_in * out.x;
                if (orientation == FT_ORIENTATION_TRUETYPE) {
                    shift.x = -shift.x;
                } else {
                    shift.y = -shift.y;
                }
                /* threshold strength to better handle collapsing segments */
                l = FT_MIN(l_in, l_out);
                q = out.x * in.y - out.y * in.x;
                if (orientation == FT_ORIENTATION_TRUETYPE) {
                    q = -q;
                }
                if (FT_MulDiv(xstrength, q, l) < d) {
                    shift.x = FT_MulDiv(shift.x, xstrength, d);
                } else {
                    shift.x = FT_MulDiv(shift.x, l, q);
                }
                if (FT_MulDiv(ystrength, q, l) < d) {
                    shift.y = FT_MulDiv(shift.y, ystrength, d);
                } else {
                    shift.y = FT_MulDiv(shift.y, l, q);
                }
            } else {
                shift.x = shift.y = 0;
            }
            outline->points[n].x = v_cur.x + xstrength + shift.x;
            outline->points[n].y = v_cur.y + ystrength + shift.y;
            in    = out;
            l_in  = l_out;
            v_cur = v_next;
        }
        first = last + 1;
    }
    return FT_Err_Ok;
}
/* documentation is in ftoutln.h */
FT_EXPORT_DEF(FT_Orientation)
FT_Outline_Get_Orientation(FT_Outline  *outline)
{
    FT_Vector  *points;
    FT_Vector   v_prev, v_cur;
    FT_Int      c, n, first;
    FT_Pos      area = 0;
    if (!outline || outline->n_points <= 0) {
        return FT_ORIENTATION_TRUETYPE;
    }
    /* We use the nonzero winding rule to find the orientation.       */
    /* Since glyph outlines behave much more `regular' than arbitrary */
    /* cubic or quadratic curves, this test deals with the polygon    */
    /* only which is spanned up by the control points.                */
    points = outline->points;
    first = 0;
    for (c = 0; c < outline->n_contours; c++) {
        FT_Int  last = outline->contours[c];
        v_prev = points[last];
        for (n = first; n <= last; n++) {
            v_cur = points[n];
            area += (v_cur.y - v_prev.y) * (v_cur.x + v_prev.x);
            v_prev = v_cur;
        }
        first = last + 1;
    }
    if (area > 0) {
        return FT_ORIENTATION_POSTSCRIPT;
    } else if (area < 0) {
        return FT_ORIENTATION_TRUETYPE;
    } else {
        return FT_ORIENTATION_NONE;
    }
}
