    FT_Byte         *subrs_block;
    FT_Byte         *charstrings_block;
    FT_Byte         *glyph_names_block;
    FT_Int           num_subrs;
    FT_Byte        **subrs;
    FT_PtrDist      *subrs_len;
    FT_Int           num_glyphs;
    /* array of glyph names       */
    FT_String      **glyph_names;
    /* array of glyph charstrings */
    FT_Byte        **charstrings;
    FT_PtrDist      *charstrings_len;
    FT_Byte          paint_type;
    FT_Byte          font_type;
    FT_Matrix        font_matrix;
