/*                                                                       */
/* BDF font options macros and types.                                    */
/*                                                                       */
/*************************************************************************/
/* Correct invalid metrics when loading. */
#define BDF_CORRECT_METRICS  0x01
/* Preserve the font comments.           */
#define BDF_KEEP_COMMENTS    0x02
/* Keep the unencoded glyphs.            */
#define BDF_KEEP_UNENCODED   0x04
/* Font has proportional spacing.        */
#define BDF_PROPORTIONAL     0x08
/* Font has mono width.                  */
#define BDF_MONOWIDTH        0x10
/* Font has charcell spacing.            */
#define BDF_CHARCELL         0x20
#define BDF_ALL_SPACING  ( BDF_PROPORTIONAL | \
                           BDF_MONOWIDTH    | \
                           BDF_CHARCELL     )
#define BDF_DEFAULT_LOAD_OPTIONS  ( BDF_CORRECT_METRICS | \
                                    BDF_KEEP_COMMENTS   | \
                                    BDF_KEEP_UNENCODED  | \
                                    BDF_PROPORTIONAL    )
typedef struct  bdf_options_t_ {
    int            correct_metrics;
    int            keep_unencoded;
    int            keep_comments;
    int            font_spacing;
} bdf_options_t;
/* Callback function type for unknown configuration options. */
typedef int
(*bdf_options_callback_t)(bdf_options_t  *opts,
                          char          **params,
                          unsigned long   nparams,
                          void           *client_data);
/*************************************************************************/
/*                                                                       */
/* BDF font property macros and types.                                   */
/*                                                                       */
/*************************************************************************/
#define BDF_ATOM      1
#define BDF_INTEGER   2
#define BDF_CARDINAL  3
/* This structure represents a particular property of a font. */
/* There are a set of defaults and each font has their own.   */
typedef struct  bdf_property_t_ {
    /* Name of the property.   */
    char  *name;
    /* Format of the property. */
    int    format;
    /* A builtin property.     */
    int    builtin;
    union {
        char          *atom;
        long           l;
        unsigned long  ul;
        /* Value of the property.  */
    } value;
} bdf_property_t;
/*************************************************************************/
/*                                                                       */
/* BDF font metric and glyph types.                                      */
/*                                                                       */
/*************************************************************************/
typedef struct  bdf_bbx_t_ {
    unsigned short  width;
    unsigned short  height;
    short           x_offset;
    short           y_offset;
    short           ascent;
    short           descent;
} bdf_bbx_t;
typedef struct  bdf_glyph_t_ {
    /* Glyph name.                          */
    char           *name;
    /* Glyph encoding.                      */
    long            encoding;
    /* Scalable width.                      */
    unsigned short  swidth;
    /* Device width.                        */
    unsigned short  dwidth;
    /* Glyph bounding box.                  */
    bdf_bbx_t       bbx;
    /* Glyph bitmap.                        */
    unsigned char  *bitmap;
    /* Number of bytes used per row.        */
    unsigned long   bpr;
    /* Number of bytes used for the bitmap. */
    unsigned short  bytes;
} bdf_glyph_t;
typedef struct  _hashnode_ {
    const char  *key;
    size_t       data;
} _hashnode, *hashnode;
typedef struct  hashtable_ {
    int        limit;
    int        size;
    int        used;
    hashnode  *table;
} hashtable;
typedef struct  bdf_glyphlist_t_ {
    /* Pad to 4-byte boundary.              */
    unsigned short  pad;
    /* Bits per pixel.                      */
    unsigned short  bpp;
    /* Beginning encoding value of glyphs.  */
    long            start;
    /* Ending encoding value of glyphs.     */
    long            end;
    /* Glyphs themselves.                   */
    bdf_glyph_t    *glyphs;
    /* Glyph structures allocated.          */
    unsigned long   glyphs_size;
    /* Glyph structures used.               */
    unsigned long   glyphs_used;
    /* Overall bounding box of glyphs.      */
    bdf_bbx_t       bbx;
} bdf_glyphlist_t;
typedef struct  bdf_font_t_ {
    /* Name of the font.                   */
    char            *name;
    /* Font bounding box.                  */
    bdf_bbx_t        bbx;
    /* Point size of the font.             */
    long             point_size;
    /* Font horizontal resolution.         */
    unsigned long    resolution_x;
    /* Font vertical resolution.           */
    unsigned long    resolution_y;
    /* Font spacing value.                 */
    int              spacing;
    /* Logical width for monowidth font.   */
    unsigned short   monowidth;
    /* Encoding of the default glyph.      */
    long             default_char;
    /* Font ascent.                        */
    long             font_ascent;
    /* Font descent.                       */
    long             font_descent;
    /* Glyph structures allocated.         */
    unsigned long    glyphs_size;
    /* Glyph structures used.              */
    unsigned long    glyphs_used;
    /* Glyphs themselves.                  */
    bdf_glyph_t     *glyphs;
    /* Unencoded glyph struct. allocated.  */
    unsigned long    unencoded_size;
    /* Unencoded glyph struct. used.       */
    unsigned long    unencoded_used;
    /* Unencoded glyphs themselves.        */
    bdf_glyph_t     *unencoded;
    /* Font properties allocated.          */
    unsigned long    props_size;
    /* Font properties used.               */
    unsigned long    props_used;
    /* Font properties themselves.         */
    bdf_property_t  *props;
    /* Font comments.                      */
    char            *comments;
    /* Length of comment string.           */
    unsigned long    comments_len;
    /* Storage used for glyph insertion.   */
    bdf_glyphlist_t  overflow;
    /* Internal data for the font.         */
    void            *internal;
    /* The size of the next two arrays must be in sync with the */
    /* size of the `have' array in the `bdf_parse_t' structure. */
    /* Bitmap indicating modified glyphs.  */
    unsigned long    nmod[34816];
    /* Bitmap indicating modified          */
    unsigned long    umod[34816];
    /* unencoded glyphs.                   */
    /* Boolean indicating font modified.   */
    unsigned short   modified;
    /* Bits per pixel.                     */
    unsigned short   bpp;
    FT_Memory        memory;
    bdf_property_t  *user_props;
    unsigned long    nuser_props;
    hashtable        proptbl;
} bdf_font_t;
/*************************************************************************/
/*                                                                       */
/* Types for load/save callbacks.                                        */
/*                                                                       */
/*************************************************************************/
/* Error codes. */
#define BDF_MISSING_START       -1
#define BDF_MISSING_FONTNAME    -2
#define BDF_MISSING_SIZE        -3
#define BDF_MISSING_CHARS       -4
#define BDF_MISSING_STARTCHAR   -5
#define BDF_MISSING_ENCODING    -6
#define BDF_MISSING_BBX         -7
#define BDF_OUT_OF_MEMORY      -20
#define BDF_INVALID_LINE      -100
/*************************************************************************/
/*                                                                       */
/* BDF font API.                                                         */
/*                                                                       */
/*************************************************************************/
FT_LOCAL(FT_Error)
bdf_load_font(FT_Stream       stream,
              FT_Memory       memory,
              bdf_options_t  *opts,
              bdf_font_t *    *font);
FT_LOCAL(void)
bdf_free_font(bdf_font_t  *font);
FT_LOCAL(bdf_property_t *)
bdf_get_property(char        *name,
                 bdf_font_t  *font);
FT_LOCAL(bdf_property_t *)
bdf_get_font_property(bdf_font_t  *font,
                      const char  *name);
