/*************************************************************************/
/*                                                                       */
/* Hash table utilities for the properties.                              */
/*                                                                       */
/*************************************************************************/
/* XXX: Replace this with FreeType's hash functions */
#define INITIAL_HT_SIZE  241
typedef void
(*hash_free_func)(hashnode  node);
static hashnode *
hash_bucket(const char  *key,
            hashtable   *ht)
{
    const char    *kp  = key;
    unsigned long  res = 0;
    hashnode      *bp  = ht->table, *ndp;
    /* Mocklisp hash function. */
    while (*kp) {
        res = (res << 5) - res + *kp++;
    }
    ndp = bp + (res % ht->size);
    while (*ndp) {
        kp = (*ndp)->key;
        if (kp[0] == key[0] && ft_strcmp(kp, key) == 0) {
            break;
        }
        ndp--;
        if (ndp < bp) {
            ndp = bp + (ht->size - 1);
        }
    }
    return ndp;
}
static FT_Error
hash_rehash(hashtable  *ht,
            FT_Memory   memory)
{
    hashnode  *obp = ht->table, *bp, *nbp;
    int        i, sz = ht->size;
    FT_Error   error = BDF_Err_Ok;
    ht->size <<= 1;
    ht->limit  = ht->size / 3;
    if (FT_NEW_ARRAY(ht->table, ht->size)) {
        goto Exit;
    }
    for (i = 0, bp = obp; i < sz; i++, bp++) {
        if (*bp) {
            nbp = hash_bucket((*bp)->key, ht);
            *nbp = *bp;
        }
    }
    FT_FREE(obp);
Exit:
    return error;
}
static FT_Error
hash_init(hashtable  *ht,
          FT_Memory   memory)
{
    int       sz = INITIAL_HT_SIZE;
    FT_Error  error = BDF_Err_Ok;
    ht->size  = sz;
    ht->limit = sz / 3;
    ht->used  = 0;
    if (FT_NEW_ARRAY(ht->table, sz)) {
        goto Exit;
    }
Exit:
    return error;
}
static void
hash_free(hashtable  *ht,
          FT_Memory   memory)
{
    if (ht != 0) {
        int        i, sz = ht->size;
        hashnode  *bp = ht->table;
        for (i = 0; i < sz; i++, bp++) {
            FT_FREE(*bp);
        }
        FT_FREE(ht->table);
    }
}
static FT_Error
hash_insert(char       *key,
            size_t      data,
            hashtable  *ht,
            FT_Memory   memory)
{
    hashnode  nn, *bp = hash_bucket(key, ht);
    FT_Error  error = BDF_Err_Ok;
    nn = *bp;
    if (!nn) {
        if (FT_NEW(nn)) {
            goto Exit;
        }
        *bp = nn;
        nn->key  = key;
        nn->data = data;
        if (ht->used >= ht->limit) {
            error = hash_rehash(ht, memory);
            if (error) {
                goto Exit;
            }
        }
        ht->used++;
    } else {
        nn->data = data;
    }
Exit:
    return error;
}
static hashnode
hash_lookup(const char *key,
            hashtable  *ht)
{
    hashnode *np = hash_bucket(key, ht);
    return *np;
}
/*************************************************************************/
/*                                                                       */
/* Utility types and functions.                                          */
/*                                                                       */
/*************************************************************************/
/* Function type for parsing lines of a BDF font. */
typedef FT_Error
(*_bdf_line_func_t)(char          *line,
                    unsigned long  linelen,
                    unsigned long  lineno,
                    void          *call_data,
                    void          *client_data);
/* List structure for splitting lines into fields. */
typedef struct  _bdf_list_t_ {
    char         **field;
    unsigned long  size;
    unsigned long  used;
    FT_Memory      memory;
} _bdf_list_t;
/* Structure used while loading BDF fonts. */
typedef struct  _bdf_parse_t_ {
    unsigned long   flags;
    unsigned long   cnt;
    unsigned long   row;
    short           minlb;
    short           maxlb;
    short           maxrb;
    short           maxas;
    short           maxds;
    short           rbearing;
    char           *glyph_name;
    long            glyph_enc;
    bdf_font_t     *font;
    bdf_options_t  *opts;
    /* must be in sync with `nmod' and `umod' */
    unsigned long   have[34816];
    /* arrays from `bdf_font_t' structure     */
    _bdf_list_t     list;
    FT_Memory       memory;
} _bdf_parse_t;
#define setsbit( m, cc ) \
          ( m[(FT_Byte)(cc) >> 3] |= (FT_Byte)( 1 << ( (cc) & 7 ) ) )
#define sbitset( m, cc ) \
          ( m[(FT_Byte)(cc) >> 3]  & ( 1 << ( (cc) & 7 ) ) )
static void
_bdf_list_init(_bdf_list_t  *list,
               FT_Memory     memory)
{
    FT_ZERO(list);
    list->memory = memory;
}
static void
_bdf_list_done(_bdf_list_t  *list)
{
    FT_Memory  memory = list->memory;
    if (memory) {
        FT_FREE(list->field);
        FT_ZERO(list);
    }
}
static FT_Error
_bdf_list_ensure(_bdf_list_t   *list,
                 /* same as _bdf_list_t.used */
                 unsigned long  num_items)
{
    FT_Error  error = BDF_Err_Ok;
    if (num_items > list->size) {
        /* same as _bdf_list_t.size */
        unsigned long  oldsize = list->size;
        unsigned long  newsize = oldsize + (oldsize >> 1) + 5;
        unsigned long  bigsize = (unsigned long)(FT_INT_MAX / sizeof(char *));
        FT_Memory      memory  = list->memory;
        if (oldsize == bigsize) {
            error = BDF_Err_Out_Of_Memory;
            goto Exit;
        } else if (newsize < oldsize || newsize > bigsize) {
            newsize = bigsize;
        }
        if (FT_RENEW_ARRAY(list->field, oldsize, newsize)) {
            goto Exit;
        }
        list->size = newsize;
    }
Exit:
    return error;
}
static void
_bdf_list_shift(_bdf_list_t   *list,
                unsigned long  n)
{
    unsigned long  i, u;
    if (list == 0 || list->used == 0 || n == 0) {
        return;
    }
    if (n >= list->used) {
        list->used = 0;
        return;
    }
    for (u = n, i = 0; u < list->used; i++, u++) {
        list->field[i] = list->field[u];
    }
    list->used -= n;
}
/* An empty string for empty fields. */
/* XXX eliminate this */
static const char  ft_empty[1] = { 0 };
static char *
_bdf_list_join(_bdf_list_t    *list,
               int             c,
               unsigned long  *alen)
{
    unsigned long  i, j;
    char           *fp, *dp;
    *alen = 0;
    if (list == 0 || list->used == 0) {
        return 0;
    }
    dp = list->field[0];
    for (i = j = 0; i < list->used; i++) {
        fp = list->field[i];
        while (*fp) {
            dp[j++] = *fp++;
        }
        if (i + 1 < list->used) {
            dp[j++] = (char)c;
        }
    }
    if (dp != ft_empty) {
        dp[j] = 0;
    }
    *alen = j;
    return dp;
}
/* The code below ensures that we have at least 4 + 1 `field' */
/* elements in `list' (which are possibly NULL) so that we    */
/* don't have to check the number of fields in most cases.    */
static FT_Error
_bdf_list_split(_bdf_list_t   *list,
                char          *separators,
                char          *line,
                unsigned long  linelen)
{
    int       mult, final_empty;
    char      *sp, *ep, *end;
    char      seps[32];
    FT_Error  error = BDF_Err_Ok;
    /* Initialize the list. */
    list->used = 0;
    if (list->size) {
        list->field[0] = (char *)ft_empty;
        list->field[1] = (char *)ft_empty;
        list->field[2] = (char *)ft_empty;
        list->field[3] = (char *)ft_empty;
        list->field[4] = (char *)ft_empty;
    }
    /* If the line is empty, then simply return. */
    if (linelen == 0 || line[0] == 0) {
        goto Exit;
    }
    /* In the original code, if the `separators' parameter is NULL or */
    /* empty, the list is split into individual bytes.  We don't need */
    /* this, so an error is signaled.                                 */
    if (separators == 0 || *separators == 0) {
        error = BDF_Err_Invalid_Argument;
        goto Exit;
    }
    /* Prepare the separator bitmap. */
    FT_MEM_ZERO(seps, 32);
    /* If the very last character of the separator string is a plus, then */
    /* set the `mult' flag to indicate that multiple separators should be */
    /* collapsed into one.                                                */
    for (mult = 0, sp = separators; sp && *sp; sp++) {
        if (*sp == '+' && *(sp + 1) == 0) {
            mult = 1;
        } else {
            setsbit(seps, *sp);
        }
    }
    /* Break the line up into fields. */
    for (final_empty = 0, sp = ep = line, end = sp + linelen;
         sp < end && *sp;) {
        /* Collect everything that is not a separator. */
        for (; *ep && !sbitset(seps, *ep); ep++)
            ;
        /* Resize the list if necessary. */
        if (list->used == list->size) {
            error = _bdf_list_ensure(list, list->used + 1);
            if (error) {
                goto Exit;
            }
        }
        /* Assign the field appropriately. */
        list->field[list->used++] = (ep > sp) ? sp : (char *)ft_empty;
        sp = ep;
        if (mult) {
            /* If multiple separators should be collapsed, do it now by */
            /* setting all the separator characters to 0.               */
            for (; *ep && sbitset(seps, *ep); ep++) {
                *ep = 0;
            }
        } else if (*ep != 0)
            /* Don't collapse multiple separators by making them 0, so just */
            /* make the one encountered 0.                                  */
        {
            *ep++ = 0;
        }
        final_empty = (ep > sp && *ep == 0);
        sp = ep;
    }
    /* Finally, NULL-terminate the list. */
    if (list->used + final_empty >= list->size) {
        error = _bdf_list_ensure(list, list->used + final_empty + 1);
        if (error) {
            goto Exit;
        }
    }
    if (final_empty) {
        list->field[list->used++] = (char *)ft_empty;
    }
    list->field[list->used] = 0;
Exit:
    return error;
}
/* this value cannot be stored in a 'char' */
#define NO_SKIP  256
static FT_Error
_bdf_readstream(FT_Stream         stream,
                _bdf_line_func_t  callback,
                void             *client_data,
                unsigned long    *lno)
{
    _bdf_line_func_t  cb;
    unsigned long     lineno, buf_size;
    int               refill, hold, to_skip;
    ptrdiff_t         bytes, start, end, cursor, avail;
    char             *buf = 0;
    FT_Memory         memory = stream->memory;
    FT_Error          error = BDF_Err_Ok;
    if (callback == 0) {
        error = BDF_Err_Invalid_Argument;
        goto Exit;
    }
    /* initial size and allocation of the input buffer */
    buf_size = 1024;
    if (FT_NEW_ARRAY(buf, buf_size)) {
        goto Exit;
    }
    cb      = callback;
    lineno  = 1;
    buf[0]  = 0;
    start   = 0;
    end     = 0;
    avail   = 0;
    cursor  = 0;
    refill  = 1;
    to_skip = NO_SKIP;
    /* make compiler happy */
    bytes   = 0;
    for (;;) {
        if (refill) {
            bytes  = (ptrdiff_t)FT_Stream_TryRead(
                         stream, (FT_Byte *)buf + cursor,
                         (FT_ULong)(buf_size - cursor));
            avail  = cursor + bytes;
            cursor = 0;
            refill = 0;
        }
        end = start;
        /* should we skip an optional character like \n or \r? */
        if (start < avail && buf[start] == to_skip) {
            start  += 1;
            to_skip = NO_SKIP;
            continue;
        }
        /* try to find the end of the line */
        while (end < avail && buf[end] != '\n' && buf[end] != '\r') {
            end++;
        }
        /* if we hit the end of the buffer, try shifting its content */
        /* or even resizing it                                       */
        if (end >= avail) {
            /* last line in file doesn't end in \r or \n */
            if (bytes == 0)
                /* ignore it then exit                       */
            {
                break;
            }
            if (start == 0) {
                /* this line is definitely too long; try resizing the input */
                /* buffer a bit to handle it.                               */
                FT_ULong  new_size;
                /* limit ourselves to 64KByte */
                if (buf_size >= 65536UL) {
                    FT_ERROR(("_bdf_readstream: " ERRMSG6, lineno));
                    error = BDF_Err_Invalid_Argument;
                    goto Exit;
                }
                new_size = buf_size * 2;
                if (FT_RENEW_ARRAY(buf, buf_size, new_size)) {
                    goto Exit;
                }
                cursor   = buf_size;
                buf_size = new_size;
            } else {
                bytes = avail - start;
                FT_MEM_COPY(buf, buf + start, bytes);
                cursor = bytes;
                avail -= bytes;
                start  = 0;
            }
            refill = 1;
            continue;
        }
        /* Temporarily NUL-terminate the line. */
        hold     = buf[end];
        buf[end] = 0;
        /* XXX: Use encoding independent value for 0x1a */
        if (buf[start] != '#' && buf[start] != 0x1a && end > start) {
            error = (*cb)(buf + start, (unsigned long)(end - start), lineno,
                          (void *)&cb, client_data);
            /* Redo if we have encountered CHARS without properties. */
            if (error == -1)
                error = (*cb)(buf + start, (unsigned long)(end - start), lineno,
                              (void *)&cb, client_data);
            if (error) {
                break;
            }
        }
        lineno  += 1;
        buf[end] = (char)hold;
        start    = end + 1;
        if (hold == '\n') {
            to_skip = '\r';
        } else if (hold == '\r') {
            to_skip = '\n';
        } else {
            to_skip = NO_SKIP;
        }
    }
    *lno = lineno;
Exit:
    FT_FREE(buf);
    return error;
}
