static FT_Error
cid_parse_dict(CID_Face     face,
               CID_Loader  *loader,
               FT_Byte     *base,
               FT_Long      size)
{
    CID_Parser  *parser = &loader->parser;
    parser->root.cursor = base;
    parser->root.limit  = base + size;
    parser->root.error  = CID_Err_Ok;
    {
        FT_Byte  *cur   = base;
        FT_Byte  *limit = cur + size;
        for (;;) {
            FT_Byte  *newlimit;
            parser->root.cursor = cur;
            cid_parser_skip_spaces(parser);
            if (parser->root.cursor >= limit) {
                newlimit = limit - 1 - 17;
            } else {
                newlimit = parser->root.cursor - 17;
            }
            /* look for `%ADOBeginFontDict' */
            for (; cur < newlimit; cur++) {
                if (*cur == '%'                                            &&
                    ft_strncmp((char *)cur, "%ADOBeginFontDict", 17) == 0) {
                    /* if /FDArray was found, then cid->num_dicts is > 0, and */
                    /* we can start increasing parser->num_dict               */
                    if (face->cid.num_dicts > 0) {
                        parser->num_dict++;
                    }
                }
            }
            cur = parser->root.cursor;
            /* no error can occur in cid_parser_skip_spaces */
            if (cur >= limit) {
                break;
            }
            cid_parser_skip_PS_token(parser);
            if (parser->root.cursor >= limit || parser->root.error) {
                break;
            }
            /* look for immediates */
            if (*cur == '/' && cur + 2 < limit) {
                FT_PtrDist  len;
                cur++;
                len = parser->root.cursor - cur;
                if (len > 0 && len < 22) {
                    /* now compare the immediate name to the keyword table */
                    T1_Field  keyword = (T1_Field)cid_field_records;
                    for (;;) {
                        FT_Byte  *name;
                        name = (FT_Byte *)keyword->ident;
                        if (!name) {
                            break;
                        }
                        if (cur[0] == name[0]                                 &&
                            len == (FT_PtrDist)ft_strlen((const char *)name)) {
                            FT_PtrDist  n;
                            for (n = 1; n < len; n++)
                                if (cur[n] != name[n]) {
                                    break;
                                }
                            if (n >= len) {
                                /* we found it - run the parsing callback */
                                parser->root.error = cid_load_keyword(face,
                                                                      loader,
                                                                      keyword);
                                if (parser->root.error) {
                                    return parser->root.error;
                                }
                                break;
                            }
                        }
                        keyword++;
                    }
                }
            }
            cur = parser->root.cursor;
        }
    }
    return parser->root.error;
}
/* read the subrmap and the subrs of each font dict */
static FT_Error
cid_read_subrs(CID_Face  face)
{
    CID_FaceInfo   cid    = &face->cid;
    FT_Memory      memory = face->root.memory;
    FT_Stream      stream = face->cid_stream;
    FT_Error       error;
    FT_Int         n;
    CID_Subrs      subr;
    FT_UInt        max_offsets = 0;
    FT_ULong      *offsets = 0;
    PSAux_Service  psaux = (PSAux_Service)face->psaux;
    if (FT_NEW_ARRAY(face->subrs, cid->num_dicts)) {
        goto Exit;
    }
    subr = face->subrs;
    for (n = 0; n < cid->num_dicts; n++, subr++) {
        CID_FaceDict  dict  = cid->font_dicts + n;
        FT_Int        lenIV = dict->private_dict.lenIV;
        FT_UInt       count, num_subrs = dict->num_subrs;
        FT_ULong      data_len;
        FT_Byte      *p;
        /* Check for possible overflow. */
        if (num_subrs == FT_UINT_MAX) {
            error = CID_Err_Syntax_Error;
            goto Fail;
        }
        /* reallocate offsets array if needed */
        if (num_subrs + 1 > max_offsets) {
            FT_UInt  new_max = FT_PAD_CEIL(num_subrs + 1, 4);
            if (new_max <= max_offsets) {
                error = CID_Err_Syntax_Error;
                goto Fail;
            }
            if (FT_RENEW_ARRAY(offsets, max_offsets, new_max)) {
                goto Fail;
            }
            max_offsets = new_max;
        }
        /* read the subrmap's offsets */
        if (FT_STREAM_SEEK(cid->data_offset + dict->subrmap_offset) ||
            FT_FRAME_ENTER((num_subrs + 1) * dict->sd_bytes)) {
            goto Fail;
        }
        p = (FT_Byte *)stream->cursor;
        for (count = 0; count <= num_subrs; count++) {
            offsets[count] = cid_get_offset(&p, (FT_Byte)dict->sd_bytes);
        }
        FT_FRAME_EXIT();
        /* offsets must be ordered */
        for (count = 1; count <= num_subrs; count++)
            if (offsets[count - 1] > offsets[count]) {
                goto Fail;
            }
        /* now, compute the size of subrs charstrings, */
        /* allocate, and read them                     */
        data_len = offsets[num_subrs] - offsets[0];
        if (FT_NEW_ARRAY(subr->code, num_subrs + 1) ||
            FT_ALLOC(subr->code[0], data_len)) {
            goto Fail;
        }
        if (FT_STREAM_SEEK(cid->data_offset + offsets[0]) ||
            FT_STREAM_READ(subr->code[0], data_len)) {
            goto Fail;
        }
        /* set up pointers */
        for (count = 1; count <= num_subrs; count++) {
            FT_ULong  len;
            len               = offsets[count] - offsets[count - 1];
            subr->code[count] = subr->code[count - 1] + len;
        }
        /* decrypt subroutines, but only if lenIV >= 0 */
        if (lenIV >= 0) {
            for (count = 0; count < num_subrs; count++) {
                FT_ULong  len;
                len = offsets[count + 1] - offsets[count];
                psaux->t1_decrypt(subr->code[count], len, 4330);
            }
        }
        subr->num_subrs = num_subrs;
    }
Exit:
    FT_FREE(offsets);
    return error;
Fail:
    if (face->subrs) {
        for (n = 0; n < cid->num_dicts; n++) {
            if (face->subrs[n].code) {
                FT_FREE(face->subrs[n].code[0]);
            }
            FT_FREE(face->subrs[n].code);
        }
        FT_FREE(face->subrs);
    }
    goto Exit;
}
static void
cid_init_loader(CID_Loader  *loader,
                CID_Face     face)
{
    FT_UNUSED(face);
    FT_MEM_ZERO(loader, sizeof(*loader));
}
static  void
cid_done_loader(CID_Loader  *loader)
{
    CID_Parser  *parser = &loader->parser;
    /* finalize parser */
    cid_parser_done(parser);
}
static FT_Error
cid_hex_to_binary(FT_Byte  *data,
                  FT_Long   data_len,
                  FT_ULong  offset,
                  CID_Face  face)
{
    FT_Stream  stream = face->root.stream;
    FT_Error   error;
    FT_Byte    buffer[256];
    FT_Byte   *p, *plimit;
    FT_Byte   *d, *dlimit;
    FT_Byte    val;
    FT_Bool    upper_nibble, done;
    if (FT_STREAM_SEEK(offset)) {
        goto Exit;
    }
    d      = data;
    dlimit = d + data_len;
    p      = buffer;
    plimit = p;
    upper_nibble = 1;
    done         = 0;
    while (d < dlimit) {
        if (p >= plimit) {
            FT_ULong  oldpos = FT_STREAM_POS();
            FT_ULong  size   = stream->size - oldpos;
            if (size == 0) {
                error = CID_Err_Syntax_Error;
                goto Exit;
            }
            if (FT_STREAM_READ(buffer, 256 > size ? size : 256)) {
                goto Exit;
            }
            p      = buffer;
            plimit = p + FT_STREAM_POS() - oldpos;
        }
        if (ft_isdigit(*p)) {
            val = (FT_Byte)(*p - '0');
        } else if (*p >= 'a' && *p <= 'f') {
            val = (FT_Byte)(*p - 'a');
        } else if (*p >= 'A' && *p <= 'F') {
            val = (FT_Byte)(*p - 'A' + 10);
        } else if (*p == ' '  ||
                   *p == '\t' ||
                   *p == '\r' ||
                   *p == '\n' ||
                   *p == '\f' ||
                   *p == '\0') {
            p++;
            continue;
        } else if (*p == '>') {
            val  = 0;
            done = 1;
        } else {
            error = CID_Err_Syntax_Error;
            goto Exit;
        }
        if (upper_nibble) {
            *d = (FT_Byte)(val << 4);
        } else {
            *d = (FT_Byte)(*d + val);
            d++;
        }
        upper_nibble = (FT_Byte)(1 - upper_nibble);
        if (done) {
            break;
        }
        p++;
    }
    error = CID_Err_Ok;
Exit:
    return error;
}
FT_LOCAL_DEF(FT_Error)
cid_face_open(CID_Face  face,
              FT_Int    face_index)
{
    CID_Loader   loader;
    CID_Parser  *parser;
    FT_Memory    memory = face->root.memory;
    FT_Error     error;
    cid_init_loader(&loader, face);
    parser = &loader.parser;
    error = cid_parser_new(parser, face->root.stream, face->root.memory,
                           (PSAux_Service)face->psaux);
    if (error) {
        goto Exit;
    }
    error = cid_parse_dict(face, &loader,
                           parser->postscript,
                           parser->postscript_len);
    if (error) {
        goto Exit;
    }
    if (face_index < 0) {
        goto Exit;
    }
    if (FT_NEW(face->cid_stream)) {
        goto Exit;
    }
    if (parser->binary_length) {
        /* we must convert the data section from hexadecimal to binary */
        if (FT_ALLOC(face->binary_data, parser->binary_length)         ||
            cid_hex_to_binary(face->binary_data, parser->binary_length,
                              parser->data_offset, face)) {
            goto Exit;
        }
        FT_Stream_OpenMemory(face->cid_stream,
                             face->binary_data, parser->binary_length);
        face->cid.data_offset = 0;
    } else {
        *face->cid_stream     = *face->root.stream;
        face->cid.data_offset = loader.parser.data_offset;
    }
    error = cid_read_subrs(face);
Exit:
    cid_done_loader(&loader);
    return error;
}
