/*
   *  POSTSCRIPT NAME SERVICE
   *
   */
static const char *
cid_get_postscript_name(CID_Face  face)
{
    const char  *result = face->cid.cid_font_name;
    if (result && result[0] == '/') {
        result++;
    }
    return result;
}
static const FT_Service_PsFontNameRec  cid_service_ps_name = {
    (FT_PsName_GetFunc) cid_get_postscript_name
};
/*
   *  POSTSCRIPT INFO SERVICE
   *
   */
static FT_Error
cid_ps_get_font_info(FT_Face          face,
                     PS_FontInfoRec  *afont_info)
{
    *afont_info = ((CID_Face)face)->cid.font_info;
    return CID_Err_Ok;
}
static FT_Error
cid_ps_get_font_extra(FT_Face          face,
                      PS_FontExtraRec  *afont_extra)
{
    *afont_extra = ((CID_Face)face)->font_extra;
    return CID_Err_Ok;
}
static const FT_Service_PsInfoRec  cid_service_ps_info = {
    (PS_GetFontInfoFunc)   cid_ps_get_font_info,
    (PS_GetFontExtraFunc)  cid_ps_get_font_extra,
    /* unsupported with CID fonts */
    (PS_HasGlyphNamesFunc) NULL,
    /* unsupported                */
    (PS_GetFontPrivateFunc)NULL,
    /* not implemented            */
    (PS_GetFontValueFunc)  NULL
};
/*
   *  CID INFO SERVICE
   *
   */
static FT_Error
cid_get_ros(CID_Face      face,
            const char *  *registry,
            const char *  *ordering,
            FT_Int       *supplement)
{
    CID_FaceInfo  cid = &face->cid;
    if (registry) {
        *registry = cid->registry;
    }
    if (ordering) {
        *ordering = cid->ordering;
    }
    if (supplement) {
        *supplement = cid->supplement;
    }
    return CID_Err_Ok;
}
static FT_Error
cid_get_is_cid(CID_Face  face,
               FT_Bool  *is_cid)
{
    FT_Error  error = CID_Err_Ok;
    FT_UNUSED(face);
    if (is_cid)
        /* cid driver is only used for CID keyed fonts */
    {
        *is_cid = 1;
    }
    return error;
}
static FT_Error
cid_get_cid_from_glyph_index(CID_Face  face,
                             FT_UInt   glyph_index,
                             FT_UInt  *cid)
{
    FT_Error  error = CID_Err_Ok;
    FT_UNUSED(face);
    if (cid)
        /* identity mapping */
    {
        *cid = glyph_index;
    }
    return error;
}
static const FT_Service_CIDRec  cid_service_cid_info = {
    (FT_CID_GetRegistryOrderingSupplementFunc)cid_get_ros,
    (FT_CID_GetIsInternallyCIDKeyedFunc)      cid_get_is_cid,
    (FT_CID_GetCIDFromGlyphIndexFunc)         cid_get_cid_from_glyph_index
};
/*
   *  SERVICE LIST
   *
   */
static const FT_ServiceDescRec  cid_services[] = {
    { FT_SERVICE_ID_XF86_NAME,            FT_XF86_FORMAT_CID },
    { FT_SERVICE_ID_POSTSCRIPT_FONT_NAME, &cid_service_ps_name },
    { FT_SERVICE_ID_POSTSCRIPT_INFO,      &cid_service_ps_info },
    { FT_SERVICE_ID_CID,                  &cid_service_cid_info },
    { NULL, NULL }
};
FT_CALLBACK_DEF(FT_Module_Interface)
cid_get_interface(FT_Module    module,
                  const char  *cid_interface)
{
    FT_UNUSED(module);
    return ft_service_list_lookup(cid_services, cid_interface);
}
