FT_LOCAL_DEF(void)
t1_decrypt(FT_Byte   *buffer,
           FT_Offset  length,
           FT_UShort  seed)
{
    PS_Conv_EexecDecode(&buffer,
                        buffer + length,
                        buffer,
                        length,
                        &seed);
}
