FT_LOCAL_DEF(FT_UInt)
PS_Conv_StringDecode(FT_Byte  **cursor,
                     FT_Byte   *limit,
                     FT_Byte   *buffer,
                     FT_Offset  n)
{
    FT_Byte  *p;
    FT_UInt   r = 0;
    for (p = *cursor; r < n && p < limit; p++) {
        FT_Byte  b;
        if (*p != '\\') {
            buffer[r++] = *p;
            continue;
        }
        p++;
        switch (*p) {
        case 'n':
            b = '\n';
            break;
        case 'r':
            b = '\r';
            break;
        case 't':
            b = '\t';
            break;
        case 'b':
            b = '\b';
            break;
        case 'f':
            b = '\f';
            break;
        case '\r':
            p++;
            if (*p != '\n') {
                b = *p;
                break;
            }
        /* no break */
        case '\n':
            continue;
            break;
        default:
            if (IS_PS_DIGIT(*p)) {
                b = *p - '0';
                p++;
                if (IS_PS_DIGIT(*p)) {
                    b = b * 8 + *p - '0';
                    p++;
                    if (IS_PS_DIGIT(*p)) {
                        b = b * 8 + *p - '0';
                    } else {
                        buffer[r++] = b;
                        b = *p;
                    }
                } else {
                    buffer[r++] = b;
                    b = *p;
                }
            } else {
                b = *p;
            }
            break;
        }
        buffer[r++] = b;
    }
    *cursor = p;
    return r;
}
