FT_CALLBACK_DEF(FT_Error)
/* PFR_Face */
pfr_get_kerning(FT_Face     pfrface,
                FT_UInt     left,
                FT_UInt     right,
                FT_Vector  *avector)
{
    PFR_Face     face = (PFR_Face)pfrface;
    PFR_PhyFont  phys = &face->phy_font;
    pfr_face_get_kerning(pfrface, left, right, avector);
    /* convert from metrics to outline units when necessary */
    if (phys->outline_resolution != phys->metrics_resolution) {
        if (avector->x != 0)
            avector->x = FT_MulDiv(avector->x, phys->outline_resolution,
                                   phys->metrics_resolution);
        if (avector->y != 0)
            avector->y = FT_MulDiv(avector->x, phys->outline_resolution,
                                   phys->metrics_resolution);
    }
    return PFR_Err_Ok;
}
/*
  *  PFR METRICS SERVICE
  *
  */
FT_CALLBACK_DEF(FT_Error)
/* PFR_Face */
pfr_get_advance(FT_Face   pfrface,
                FT_UInt   gindex,
                FT_Pos   *anadvance)
{
    PFR_Face  face  = (PFR_Face)pfrface;
    FT_Error  error = PFR_Err_Invalid_Argument;
    *anadvance = 0;
    if (!gindex) {
        goto Exit;
    }
    gindex--;
    if (face) {
        PFR_PhyFont  phys = &face->phy_font;
        if (gindex < phys->num_chars) {
            *anadvance = phys->chars[gindex].advance;
            error = PFR_Err_Ok;
        }
    }
Exit:
    return error;
}
FT_CALLBACK_DEF(FT_Error)
/* PFR_Face */
pfr_get_metrics(FT_Face    pfrface,
                FT_UInt   *anoutline_resolution,
                FT_UInt   *ametrics_resolution,
                FT_Fixed  *ametrics_x_scale,
                FT_Fixed  *ametrics_y_scale)
{
    PFR_Face     face = (PFR_Face)pfrface;
    PFR_PhyFont  phys = &face->phy_font;
    FT_Fixed     x_scale, y_scale;
    FT_Size      size = face->root.size;
    if (anoutline_resolution) {
        *anoutline_resolution = phys->outline_resolution;
    }
    if (ametrics_resolution) {
        *ametrics_resolution = phys->metrics_resolution;
    }
    x_scale = 0x10000L;
    y_scale = 0x10000L;
    if (size) {
        x_scale = FT_DivFix(size->metrics.x_ppem << 6,
                            phys->metrics_resolution);
        y_scale = FT_DivFix(size->metrics.y_ppem << 6,
                            phys->metrics_resolution);
    }
    if (ametrics_x_scale) {
        *ametrics_x_scale = x_scale;
    }
    if (ametrics_y_scale) {
        *ametrics_y_scale = y_scale;
    }
    return PFR_Err_Ok;
}
