    /* Bit 3: profile orientation (up/down)     */
    /* Bit 4: is top profile?                   */
    /* Bit 5: is bottom profile?                */
    /* profile's height in scanlines            */
    long        height;
    /* profile's starting scanline              */
    long        start;
    /* number of lines to step before this      */
    unsigned    countL;
