/* NOTE: These operations are only valid on 2's complement processors */
#undef FLOOR
#undef CEILING
#undef TRUNC
#undef SCALED
#define FLOOR( x )    ( (x) & -ras.precision )
#define CEILING( x )  ( ( (x) + ras.precision - 1 ) & -ras.precision )
#define TRUNC( x )    ( (signed long)(x) >> ras.precision_bits )
#define FRAC( x )     ( (x) & ( ras.precision - 1 ) )
#define SCALED( x )   ( ( (x) << ras.scale_shift ) - ras.precision_half )
#define IS_BOTTOM_OVERSHOOT( x )  ( CEILING( x ) - x >= ras.precision_half )
#define IS_TOP_OVERSHOOT( x )     ( x - FLOOR( x ) >= ras.precision_half )
/* The most used variables are positioned at the top of the structure. */
/* Thus, their offset can be coded with less opcodes, resulting in a   */
/* smaller executable.                                                 */
struct  black_TWorker_ {
    /* precision related variables         */
    Int         precision_bits;
    Int         precision;
    Int         precision_half;
    Int         precision_shift;
    Int         precision_step;
    Int         precision_jitter;
    /* == precision_shift   for bitmaps    */
    Int         scale_shift;
    /* == precision_shift+1 for pixmaps    */
    /* The profiles buffer                 */
    PLong       buff;
    /* Render pool size                    */
    PLong       sizeBuff;
    /* Profiles buffer size                */
    PLong       maxBuff;
    /* Current cursor in buffer            */
    PLong       top;
    FT_Error    error;
    /* number of Y-turns in outline        */
    Int         numTurns;
    /* current Bezier arc pointer          */
    TPoint     *arc;
    /* target bitmap width                 */
    UShort      bWidth;
    /* target bitmap buffer                */
    PByte       bTarget;
    /* target pixmap buffer                */
    PByte       gTarget;
    Long        lastX, lastY;
    Long        minY, maxY;
    /* current number of profiles          */
    UShort      num_Profs;
    /* signals a fresh new profile which   */
    Bool        fresh;
    /* `start' field must be completed     */
    /* signals that the last arc ended     */
    Bool        joint;
    /* exactly on a scanline.  Allows      */
    /* removal of doublets                 */
    /* current profile                     */
    PProfile    cProfile;
    /* head of linked list of profiles     */
    PProfile    fProfile;
    /* contour's first profile in case     */
    PProfile    gProfile;
    /* of impact                           */
    /* rendering state                     */
    TStates     state;
    /* description of target bit/pixmap    */
    FT_Bitmap   target;
    FT_Outline  outline;
    /* current offset in target bitmap     */
    Long        traceOfs;
    /* current offset in target pixmap     */
    Long        traceG;
    /* sweep's increment in target bitmap  */
    Short       traceIncr;
    /* current min x during gray rendering */
    Short       gray_min_x;
    /* current max x during gray rendering */
    Short       gray_max_x;
    /* dispatch variables */
    Function_Sweep_Init  *Proc_Sweep_Init;
    Function_Sweep_Span  *Proc_Sweep_Span;
    Function_Sweep_Span  *Proc_Sweep_Drop;
    Function_Sweep_Step  *Proc_Sweep_Step;
    /* current drop_out control method     */
    Byte        dropOutControl;
    /* indicates whether a horizontal pass */
    Bool        second_pass;
    /* should be performed to control      */
    /* drop-out accurately when calling    */
    /* Render_Glyph.  Note that there is   */
    /* no horizontal pass during gray      */
    /* rendering.                          */
    /* The Bezier stack               */
    TPoint      arcs[3 * MaxBezier + 1];
    /* band stack used for sub-banding     */
    black_TBand  band_stack[16];
    /* band stack top                      */
    Int          band_top;
#ifdef FT_RASTER_OPTION_ANTI_ALIASING
    Byte       *grays;
    Byte        gray_lines[RASTER_GRAY_LINES];
    /* Intermediate table used to render the   */
    /* graylevels pixmaps.                     */
    /* gray_lines is a buffer holding two      */
    /* monochrome scanlines                    */
    /* width in bytes of one monochrome        */
    Short       gray_width;
    /* intermediate scanline of gray_lines.    */
    /* Each gray pixel takes 2 bits long there */
    /* The gray_lines must hold 2 lines, thus with size */
    /* in bytes of at least `gray_width*2'.             */
    /* FT_RASTER_ANTI_ALIASING */
#endif
};
