FT_LOCAL_DEF(AF_Angle)
af_angle_atan(FT_Fixed  dx,
              FT_Fixed  dy)
{
    AF_Angle  angle;
    /* check trivial cases */
    if (dy == 0) {
        angle = 0;
        if (dx < 0) {
            angle = AF_ANGLE_PI;
        }
        return angle;
    } else if (dx == 0) {
        angle = AF_ANGLE_PI2;
        if (dy < 0) {
            angle = -AF_ANGLE_PI2;
        }
        return angle;
    }
    angle = 0;
    if (dx < 0) {
        dx = -dx;
        dy = -dy;
        angle = AF_ANGLE_PI;
    }
    if (dy < 0) {
        FT_Pos  tmp;
        tmp = dx;
        dx  = -dy;
        dy  = tmp;
        angle -= AF_ANGLE_PI2;
    }
    if (dx == 0 && dy == 0) {
        return 0;
    }
    if (dx == dy) {
        angle += AF_ANGLE_PI4;
    } else if (dx > dy) {
        angle += af_arctan[FT_DivFix(dy, dx) >> (16 - AF_ATAN_BITS)];
    } else
        angle += AF_ANGLE_PI2 -
                 af_arctan[FT_DivFix(dx, dy) >> (16 - AF_ATAN_BITS)];
    if (angle > AF_ANGLE_PI) {
        angle -= AF_ANGLE_2PI;
    }
    return angle;
}
