    /* the default stem thickness */
    FT_Pos           standard_width;
    /* is standard width very light? */
    FT_Bool          extra_light;
    /* ignored for horizontal metrics */
    FT_UInt          blue_count;
    AF_LatinBlueRec  blues[AF_LATIN_BLUE_MAX];
    FT_Fixed         org_scale;
    FT_Pos           org_delta;
