/* Compute the script index of each glyph within a given face. */
static FT_Error
af_face_globals_compute_script_coverage(AF_FaceGlobals  globals)
{
    FT_Error    error       = AF_Err_Ok;
    FT_Face     face        = globals->face;
    FT_CharMap  old_charmap = face->charmap;
    FT_Byte    *gscripts    = globals->glyph_scripts;
    FT_UInt     ss;
    FT_UInt     i;
    /* the value AF_SCRIPT_NONE means `uncovered glyph' */
    FT_MEM_SET(globals->glyph_scripts,
               AF_SCRIPT_NONE,
               globals->glyph_count);
    error = FT_Select_Charmap(face, FT_ENCODING_UNICODE);
    if (error) {
        /*
              *  Ignore this error; we simply use the fallback script.
              *  XXX: Shouldn't we rather disable hinting?
              */
        error = AF_Err_Ok;
        goto Exit;
    }
    /* scan each script in a Unicode charmap */
    for (ss = 0; AF_SCRIPT_CLASSES_GET[ss]; ss++) {
        AF_ScriptClass      clazz = AF_SCRIPT_CLASSES_GET[ss];
        AF_Script_UniRange  range;
        if (clazz->script_uni_ranges == NULL) {
            continue;
        }
        /*
               *  Scan all Unicode points in the range and set the corresponding
               *  glyph script index.
               */
        for (range = clazz->script_uni_ranges; range->first != 0; range++) {
            FT_ULong  charcode = range->first;
            FT_UInt   gindex;
            gindex = FT_Get_Char_Index(face, charcode);
            if (gindex != 0                             &&
                gindex < (FT_ULong)globals->glyph_count &&
                gscripts[gindex] == AF_SCRIPT_NONE) {
                gscripts[gindex] = (FT_Byte)ss;
            }
            for (;;) {
                charcode = FT_Get_Next_Char(face, charcode, &gindex);
                if (gindex == 0 || charcode > range->last) {
                    break;
                }
                if (gindex < (FT_ULong)globals->glyph_count &&
                    gscripts[gindex] == AF_SCRIPT_NONE) {
                    gscripts[gindex] = (FT_Byte)ss;
                }
            }
        }
    }
    /* mark ASCII digits */
    for (i = 0x30; i <= 0x39; i++) {
        FT_UInt  gindex = FT_Get_Char_Index(face, i);
        if (gindex != 0 && gindex < (FT_ULong)globals->glyph_count) {
            gscripts[gindex] |= AF_DIGIT;
        }
    }
Exit:
    /*
         *  By default, all uncovered glyphs are set to the fallback script.
         *  XXX: Shouldn't we disable hinting or do something similar?
         */
    if (globals->module->fallback_script != AF_SCRIPT_NONE) {
        FT_Long  nn;
        for (nn = 0; nn < globals->glyph_count; nn++) {
            if ((gscripts[nn] & ~AF_DIGIT) == AF_SCRIPT_NONE) {
                gscripts[nn] &= ~AF_SCRIPT_NONE;
                gscripts[nn] |= globals->module->fallback_script;
            }
        }
    }
    FT_Set_Charmap(face, old_charmap);
    return error;
}
FT_LOCAL_DEF(FT_Error)
af_face_globals_new(FT_Face          face,
                    AF_FaceGlobals  *aglobals,
                    AF_Module        module)
{
    FT_Error        error;
    FT_Memory       memory;
    AF_FaceGlobals  globals = NULL;
    memory = face->memory;
    if (FT_ALLOC(globals, sizeof(*globals) +
                 face->num_glyphs * sizeof(FT_Byte))) {
        goto Exit;
    }
    globals->face          = face;
    globals->glyph_count   = face->num_glyphs;
    globals->glyph_scripts = (FT_Byte *)(globals + 1);
    globals->module        = module;
    error = af_face_globals_compute_script_coverage(globals);
    if (error) {
        af_face_globals_free(globals);
        globals = NULL;
    }
    globals->increase_x_height = AF_PROP_INCREASE_X_HEIGHT_MAX;
Exit:
    *aglobals = globals;
    return error;
}
FT_LOCAL_DEF(void)
af_face_globals_free(AF_FaceGlobals  globals)
{
    if (globals) {
        FT_Memory  memory = globals->face->memory;
        FT_UInt    nn;
        for (nn = 0; nn < AF_SCRIPT_MAX; nn++) {
            if (globals->metrics[nn]) {
                AF_ScriptClass  clazz = AF_SCRIPT_CLASSES_GET[nn];
                FT_ASSERT(globals->metrics[nn]->clazz == clazz);
                if (clazz->script_metrics_done) {
                    clazz->script_metrics_done(globals->metrics[nn]);
                }
                FT_FREE(globals->metrics[nn]);
            }
        }
        globals->glyph_count   = 0;
        /* no need to free this one! */
        globals->glyph_scripts = NULL;
        globals->face          = NULL;
        FT_FREE(globals);
    }
}
FT_LOCAL_DEF(FT_Error)
af_face_globals_get_metrics(AF_FaceGlobals     globals,
                            FT_UInt            gindex,
                            FT_UInt            options,
                            AF_ScriptMetrics  *ametrics)
{
    AF_ScriptMetrics  metrics = NULL;
    FT_UInt           gidx;
    AF_ScriptClass    clazz;
    FT_UInt           script     = options & 15;
    const FT_Offset   script_max = sizeof(AF_SCRIPT_CLASSES_GET) /
                                   sizeof(AF_SCRIPT_CLASSES_GET[0]);
    FT_Error          error      = AF_Err_Ok;
    if (gindex >= (FT_ULong)globals->glyph_count) {
        error = AF_Err_Invalid_Argument;
        goto Exit;
    }
    gidx = script;
    if (gidx == 0 || gidx + 1 >= script_max) {
        gidx = globals->glyph_scripts[gindex] & AF_SCRIPT_NONE;
    }
    clazz = AF_SCRIPT_CLASSES_GET[gidx];
    if (script == 0) {
        script = clazz->script;
    }
    metrics = globals->metrics[clazz->script];
    if (metrics == NULL) {
        /* create the global metrics object if necessary */
        FT_Memory  memory = globals->face->memory;
        if (FT_ALLOC(metrics, clazz->script_metrics_size)) {
            goto Exit;
        }
        metrics->clazz   = clazz;
        metrics->globals = globals;
        if (clazz->script_metrics_init) {
            error = clazz->script_metrics_init(metrics, globals->face);
            if (error) {
                if (clazz->script_metrics_done) {
                    clazz->script_metrics_done(metrics);
                }
                FT_FREE(metrics);
                goto Exit;
            }
        }
        globals->metrics[clazz->script] = metrics;
    }
Exit:
    *ametrics = metrics;
    return error;
}
FT_LOCAL_DEF(FT_Bool)
af_face_globals_is_digit(AF_FaceGlobals  globals,
                         FT_UInt         gindex)
{
    if (gindex < (FT_ULong)globals->glyph_count) {
        return (FT_Bool)(globals->glyph_scripts[gindex] & AF_DIGIT);
    }
    return (FT_Bool)0;
}
