/*************************************************************************/
/*                                                                       */
/* The macro FT_COMPONENT is used in trace mode.  It is an implicit      */
/* parameter of the FT_TRACE() and FT_ERROR() macros, used to print/log  */
/* messages during execution.                                            */
/*                                                                       */
#undef  FT_COMPONENT
#define FT_COMPONENT  trace_afcjk
/*************************************************************************/
/*************************************************************************/
/*****                                                               *****/
/*****              C J K   G L O B A L   M E T R I C S              *****/
/*****                                                               *****/
/*************************************************************************/
/*************************************************************************/
/* Basically the Latin version with AF_CJKMetrics */
/* to replace AF_LatinMetrics.                    */
FT_LOCAL_DEF(void)
af_cjk_metrics_init_widths(AF_CJKMetrics  metrics,
                           FT_Face        face)
{
    /* scan the array of segments in each direction */
    AF_GlyphHintsRec  hints[1];
    af_glyph_hints_init(hints, face->memory);
    metrics->axis[AF_DIMENSION_HORZ].width_count = 0;
    metrics->axis[AF_DIMENSION_VERT].width_count = 0;
    {
        FT_Error          error;
        FT_UInt           glyph_index;
        int               dim;
        AF_CJKMetricsRec  dummy[1];
        AF_Scaler         scaler = &dummy->root.scaler;
        glyph_index = FT_Get_Char_Index(face,
                                        metrics->root.clazz->standard_char);
        if (glyph_index == 0) {
            goto Exit;
        }
        error = FT_Load_Glyph(face, glyph_index, FT_LOAD_NO_SCALE);
        if (error || face->glyph->outline.n_points <= 0) {
            goto Exit;
        }
        FT_ZERO(dummy);
        dummy->units_per_em = metrics->units_per_em;
        scaler->x_scale = 0x10000L;
        scaler->y_scale = 0x10000L;
        scaler->x_delta = 0;
        scaler->y_delta = 0;
        scaler->face        = face;
        scaler->render_mode = FT_RENDER_MODE_NORMAL;
        scaler->flags       = 0;
        af_glyph_hints_rescale(hints, (AF_ScriptMetrics)dummy);
        error = af_glyph_hints_reload(hints, &face->glyph->outline);
        if (error) {
            goto Exit;
        }
        for (dim = 0; dim < AF_DIMENSION_MAX; dim++) {
            AF_CJKAxis    axis    = &metrics->axis[dim];
            AF_AxisHints  axhints = &hints->axis[dim];
            AF_Segment    seg, limit, link;
            FT_UInt       num_widths = 0;
            error = af_latin_hints_compute_segments(hints, (AF_Dimension)dim);
            if (error) {
                goto Exit;
            }
            af_latin_hints_link_segments(hints, (AF_Dimension)dim);
            seg   = axhints->segments;
            limit = seg + axhints->num_segments;
            for (; seg < limit; seg++) {
                link = seg->link;
                /* we only consider stem segments there! */
                if (link && link->link == seg && link > seg) {
                    FT_Pos  dist;
                    dist = seg->pos - link->pos;
                    if (dist < 0) {
                        dist = -dist;
                    }
                    if (num_widths < AF_CJK_MAX_WIDTHS) {
                        axis->widths[num_widths++].org = dist;
                    }
                }
            }
            /* this also replaces multiple almost identical stem widths */
            /* with a single one (the value 100 is heuristic) */
            af_sort_and_quantize_widths(&num_widths, axis->widths,
                                        dummy->units_per_em / 100);
            axis->width_count = num_widths;
        }
Exit:
        for (dim = 0; dim < AF_DIMENSION_MAX; dim++) {
            AF_CJKAxis  axis = &metrics->axis[dim];
            FT_Pos      stdw;
            stdw = (axis->width_count > 0) ? axis->widths[0].org
                   : AF_LATIN_CONSTANT(metrics, 50);
            /* let's try 20% of the smallest width */
            axis->edge_distance_threshold = stdw / 5;
            axis->standard_width          = stdw;
            axis->extra_light             = 0;
        }
    }
    af_glyph_hints_done(hints);
}
